#!/bin/bash
# DIE-QC-41 F1d adapter (M6-entry drawn via src_pc die_clock_128 fix, outward M8 patch, root off M9 strap, F1=1 + FUT=ref fixed_wires -> pad clear of later trunks). DIE-QC-40: Codex N4-indexed adapter (0.032 CR.SPACE) on native-reserved backbone RN1/RN1c. Derived from DIE-QC-39 LEAF: leaf-driver A-pin loads (access vs R7 re-sited stacks) + variant D (PROV=A NAT=1 NEAR_A) + native landing-row reserve OT_DQC39_LANDRES=$4 (band|all)
# If bb1 has unresolved pins, they are run WITHOUT a record (default column window) in a DIAGNOSTIC copy (status relabelled,
# failures kept in the file) -> measures the remaining stage, not a qualification.
set -euo pipefail
Q=/srv/opentallas-scratch2/claude; R=$Q/die-qc36; S=$Q/die-qc34; C=$Q/codex-qc-import-0824; M=$Q/codex-qc-mesh5-1029; PC=$Q/codex-qc-provider-clock-0834
V=$1; O=/srv/opentallas-scratch2/claude/die-qc41/prov_$V$2; mkdir -p $O
python3 -c "
import json; p=json.load(open(\"/srv/opentallas-scratch2/claude/die-qc40/bb/$V/backbone_plan.json\")); p[\"source_status\"]=p[\"status\"]; p[\"status\"]=\"PASS_GEOMETRY\"; p[\"diagnostic_partial\"]=bool(p[\"failures\"]); json.dump(p,open(\"$O/backbone_plan_e3.json\",\"w\"))"
docker run --rm -e OT_DQC40_F1=${F1:-0} -e OT_DQC40_F1RES=0 -e OT_DQC41_FUTURE=${FUT:-} -e OT_DQC41_ROOTX=1 -e OT_DQC41_ROOTRES=1 -e OT_DQC41_FIRST=${FIRST:-} -e OT_DQC41_NOBB=${NOBB:-} -e OT_DQC38_PROV=A -e OT_DQC38_NAT=1 -e OT_DQC38_NEAR_A=$3 -e OT_DQC39_LANDRES=$4 -e OT_DQC39_JOGX=$5 --name dieqc41-$V$2-$$ --memory=64g --memory-swap=64g --cpus=4 -v "$Q:$Q" -w "$R" python:3.12 bash -c "set -e; trap \"chown -R 1000:1000 $O\" EXIT; pip -q install matplotlib shapely numpy pyyaml jsonschema >/dev/null 2>&1; cd /srv/opentallas-scratch2/claude/die-qc41/src_pc/tools/clk; python fixed_tree_provider.py --base-adapter /srv/opentallas-scratch2/claude/die-qc41/fixed_tree_prov_f1d_r.py --repo /srv/opentallas-scratch2/claude/die-qc41/src_pc --provider-clock-loads $Q/die-qc39/access_leaf_resite/clock_loads_access.json --provider-bindings $Q/qc-import-1/bound/bindings.json --provider-via-facts $M/census119_h800/probe_census.json --native-clock-landings $Q/die-qc29/formA/census_full/landing_plan.json --phy-clock-stubs $Q/die-qc30/b1/phy_stub_plan.json --tree $R/resite/tree_resite.json --netlist $C/reachfix/mechanics/clkonly.v --lef $Q/codex-qc-physical-1029/inputs/cells.lef --plan $Q/qc-import-1/plan/plan_qc_import1.json --endpoints $C/reachfix/mechanics/endpoints.json --tech-vias $M/census119_h800/probe_census.json --backbone-plan $O/backbone_plan_e3.json --out $O > $O/run.log 2>&1"
